def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n >= 100:
        opp_def = sum(1 for m, o in history if o == 'D')
        return 'D' if opp_def * 3 < n else 'C'

    opp_def = sum(1 for m, o in history if o == 'D')
    my_def = sum(1 for m, o in history if m == 'D')
    opp_coop = n - opp_def
    recent = history[-8:]
    recent_opp_def = sum(1 for m, o in recent if o == 'D')
    recent_my_def = sum(1 for m, o in recent if m == 'D')
    last_my, last_opp = history[-1]

    if n >= 92:
        if opp_def * 4 <= n:
            return 'D'
        if recent_opp_def <= 1:
            return 'D'
        return 'C'

    if opp_def == 0:
        if n >= 30 and n % 9 == 5:
            return 'D'
        return 'C'

    if recent_opp_def == 0:
        if my_def > 0 and last_opp == 'C' and opp_def * 6 < n:
            if my_def >= 2 and n >= 25:
                return 'C'
        return 'C'

    if opp_def * 5 >= n * 4 and n >= 6:
        if recent_opp_def >= 5:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if recent_opp_def >= 5:
        return 'D'

    if recent_opp_def >= 3:
        if recent_my_def >= 3:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        if last_opp == 'D' and last_my == 'D':
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    if recent_opp_def == 2:
        if last_opp == 'D':
            if last_my == 'D':
                if opp_def * 3 < n:
                    return 'C'
                return 'D'
            return 'D'
        return 'C'

    if recent_opp_def == 1:
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            if opp_def * 8 < n and recent_my_def <= 2:
                return 'C'
            return 'D'
        return 'C'

    return 'C'
